interface EstadoPedido {
  aCarregar: boolean;
  dados?: string[];
  erro?: string;
}

function descrever(estado: EstadoPedido): string {
  if (estado.aCarregar) {
    return "A carregar...";
  }
  if (estado.erro !== undefined) {
    return "Falhou: " + estado.erro;
  }
  // @ts-expect-error dados continua opcional: o compilador não sabe que só sobrou o caso de sucesso
  return estado.dados.join(", ");
}

// nada impede um estado impossível: a carregar, com dados e com erro ao mesmo tempo
const impossivel: EstadoPedido = { aCarregar: true, dados: ["a"], erro: "timeout" };

console.log(descrever({ aCarregar: false, erro: "404" })); // "Falhou: 404"
console.log(impossivel.erro); // "timeout"

type Circulo = { kind: "circulo"; raio: number };
type Quadrado = { kind: "quadrado"; lado: number };
type Forma = Circulo | Quadrado;

function medida(forma: Forma): number {
  console.log(forma.kind); // kind existe em todos os membros, logo está sempre disponível

  // @ts-expect-error raio não existe em Quadrado, logo não existe na união
  console.log(forma.raio);

  if (forma.kind === "circulo") {
    return forma.raio; // aqui forma é Circulo
  }
  return forma.lado; // e aqui é Quadrado
}

console.log(medida({ kind: "circulo", raio: 2 })); // 2
console.log(medida({ kind: "quadrado", lado: 5 })); // 5

// @ts-expect-error losango não é um dos literais declarados no discriminante kind
const invalida: Forma = { kind: "losango", lado: 3 };
console.log(invalida.kind);

type Pedido =
  | { estado: "inativo" }
  | { estado: "aCarregar"; desdeMs: number }
  | { estado: "sucesso"; dados: string[] }
  | { estado: "erro"; codigo: number; mensagem: string };

function mensagemDe(pedido: Pedido): string {
  switch (pedido.estado) {
    case "inativo":
      return "Ainda nao foi pedido nada.";
    case "aCarregar":
      return "A carregar ha " + pedido.desdeMs + " ms.";
    case "sucesso":
      return pedido.dados.length + " resultados.";
    case "erro":
      return "Erro " + pedido.codigo + ": " + pedido.mensagem;
  }
}

// o mesmo estreitamento com if/else encadeado: no último else só sobra o membro erro
function mensagemComIf(pedido: Pedido): string {
  if (pedido.estado === "inativo") {
    return "Ainda nao foi pedido nada.";
  } else if (pedido.estado === "aCarregar") {
    return "A carregar ha " + pedido.desdeMs + " ms.";
  } else if (pedido.estado === "sucesso") {
    return pedido.dados.length + " resultados.";
  } else {
    return "Erro " + pedido.codigo + ": " + pedido.mensagem;
  }
}

console.log(mensagemDe({ estado: "aCarregar", desdeMs: 250 })); // "A carregar ha 250 ms."
console.log(mensagemDe({ estado: "sucesso", dados: ["a", "b"] })); // "2 resultados."
console.log(mensagemComIf({ estado: "erro", codigo: 404, mensagem: "nao encontrado" })); // "Erro 404: nao encontrado"

type Forma =
  | { kind: "circulo"; raio: number }
  | { kind: "retangulo"; largura: number; altura: number }
  | { kind: "triangulo"; base: number; altura: number };

function area(forma: Forma): number {
  switch (forma.kind) {
    case "circulo":
      return Math.PI * forma.raio ** 2;
    case "retangulo":
      return forma.largura * forma.altura;
    case "triangulo":
      return (forma.base * forma.altura) / 2;
  }
}

console.log(area({ kind: "retangulo", largura: 3, altura: 4 })); // 12
console.log(area({ kind: "triangulo", base: 6, altura: 5 })); // 15
console.log(area({ kind: "circulo", raio: 1 }).toFixed(2)); // "3.14"

// @ts-expect-error o membro triangulo precisa de base, e largura não lhe pertence
const errada: Forma = { kind: "triangulo", largura: 6, altura: 5 };
console.log(errada.kind);

type Evento =
  | { tipo: "clique"; x: number; y: number }
  | { tipo: "tecla"; tecla: string }
  | { tipo: "scroll"; delta: number };

const eventos: Evento[] = [
  { tipo: "clique", x: 10, y: 20 },
  { tipo: "tecla", tecla: "Enter" },
  { tipo: "scroll", delta: -120 },
  { tipo: "clique", x: 5, y: 5 },
];

let cliques = 0;
for (const evento of eventos) {
  switch (evento.tipo) {
    case "clique":
      cliques += 1;
      console.log("clique em " + evento.x + "," + evento.y);
      break;
    case "tecla":
      console.log("tecla " + evento.tecla.toLowerCase());
      break;
    case "scroll":
      console.log("scroll de " + Math.abs(evento.delta));
      break;
  }
}
console.log(cliques); // 2

// o discriminante também pode estar numa propriedade aninhada
type Notificacao = {
  id: number;
  corpo: { formato: "texto"; texto: string } | { formato: "imagem"; url: string; largura: number };
};

function resumo(notificacao: Notificacao): string {
  if (notificacao.corpo.formato === "texto") {
    return notificacao.id + ": " + notificacao.corpo.texto;
  }
  return notificacao.id + ": imagem de " + notificacao.corpo.largura + " px";
}

console.log(resumo({ id: 1, corpo: { formato: "texto", texto: "ola" } })); // "1: ola"
console.log(resumo({ id: 2, corpo: { formato: "imagem", url: "/a.png", largura: 800 } })); // "2: imagem de 800 px"

// o filter compara o discriminante, e o array devolvido já vem estreitado
const soCliques = eventos.filter((evento) => evento.tipo === "clique");
console.log(soCliques.length); // 2
console.log(soCliques[0].x); // 10

