// Com um discriminante de string, só se escrevem os estados que existem mesmo
type Tarefa =
  | { status: "pendente" }
  | { status: "concluida"; valor: number }
  | { status: "falhada"; motivo: string };

// @ts-expect-error cancelada não é um dos literais de status
const inventada: Tarefa = { status: "cancelada" };
console.log(inventada.status);

// @ts-expect-error o membro concluida exige a propriedade valor
const incompleta: Tarefa = { status: "concluida" };
console.log(incompleta.status);

function relatorio(tarefa: Tarefa): string {
  if (tarefa.status === "concluida") {
    return "Valor: " + tarefa.valor;
  }
  if (tarefa.status === "falhada") {
    return "Motivo: " + tarefa.motivo;
  }
  return "Por fazer.";
}

console.log(relatorio({ status: "concluida", valor: 42 })); // "Valor: 42"
console.log(relatorio({ status: "pendente" })); // "Por fazer."

