type Pagamento =
  | { metodo: "cartao"; ultimosQuatro: string }
  | { metodo: "mbway"; telemovel: string };

function descrever(pagamento: Pagamento): string {
  if (pagamento.metodo === "cartao") {
    return "Cartao terminado em " + pagamento.ultimosQuatro;
  }
  return "MB WAY para o numero " + pagamento.telemovel;
}

console.log(descrever({ metodo: "cartao", ultimosQuatro: "4321" })); // "Cartao terminado em 4321"
console.log(descrever({ metodo: "mbway", telemovel: "912345678" })); // "MB WAY para o numero 912345678"

type Upload =
  | { fase: "parado" }
  | { fase: "aEnviar"; percentagem: number }
  | { fase: "terminado"; url: string }
  | { fase: "falhado"; motivo: string };

function estadoDoUpload(upload: Upload): string {
  switch (upload.fase) {
    case "parado":
      return "Escolha um ficheiro.";
    case "aEnviar":
      return "A enviar: " + upload.percentagem + "%";
    case "terminado":
      return "Disponivel em " + upload.url;
    case "falhado":
      return "Falhou: " + upload.motivo;
  }
}

console.log(estadoDoUpload({ fase: "parado" })); // "Escolha um ficheiro."
console.log(estadoDoUpload({ fase: "aEnviar", percentagem: 40 })); // "A enviar: 40%"
console.log(estadoDoUpload({ fase: "terminado", url: "/f/1.pdf" })); // "Disponivel em /f/1.pdf"
console.log(estadoDoUpload({ fase: "falhado", motivo: "ficheiro grande demais" })); // "Falhou: ficheiro grande demais"

type Figura =
  | { forma: "quadrado"; lado: number }
  | { forma: "retangulo"; largura: number; altura: number }
  | { forma: "circulo"; raio: number };

function perimetro(figura: Figura): number {
  switch (figura.forma) {
    case "quadrado":
      return figura.lado * 4;
    case "retangulo":
      return (figura.largura + figura.altura) * 2;
    case "circulo":
      return 2 * Math.PI * figura.raio;
  }
}

const figuras: Figura[] = [
  { forma: "quadrado", lado: 3 },
  { forma: "retangulo", largura: 2, altura: 5 },
  { forma: "circulo", raio: 2 },
];

for (const figura of figuras) {
  console.log(figura.forma + ": " + perimetro(figura).toFixed(2));
}
// "quadrado: 12.00"
// "retangulo: 14.00"
// "circulo: 12.57"

type Operacao =
  | { tipo: "adicionar"; preco: number; quantidade: number }
  | { tipo: "remover"; preco: number; quantidade: number }
  | { tipo: "desconto"; desconto: { modo: "percentagem"; pontos: number } | { modo: "fixo"; euros: number } }
  | { tipo: "portes"; valor: number };

function total(operacoes: Operacao[]): number {
  let valor = 0;
  for (const operacao of operacoes) {
    switch (operacao.tipo) {
      case "adicionar":
        valor += operacao.preco * operacao.quantidade;
        break;
      case "remover":
        valor -= operacao.preco * operacao.quantidade;
        break;
      case "desconto":
        // segundo nível de estreitamento, agora sobre o discriminante aninhado
        if (operacao.desconto.modo === "percentagem") {
          valor -= (valor * operacao.desconto.pontos) / 100;
        } else {
          valor -= operacao.desconto.euros;
        }
        break;
      case "portes":
        valor += operacao.valor;
        break;
    }
  }
  return valor;
}

const carrinho: Operacao[] = [
  { tipo: "adicionar", preco: 10, quantidade: 2 },
  { tipo: "adicionar", preco: 5, quantidade: 1 },
  { tipo: "remover", preco: 5, quantidade: 1 },
  { tipo: "desconto", desconto: { modo: "percentagem", pontos: 10 } },
  { tipo: "desconto", desconto: { modo: "fixo", euros: 2 } },
  { tipo: "portes", valor: 4 },
];

console.log(total(carrinho).toFixed(2)); // "20.00"
